 	const MetaName& fieldName, bool topLevel)
 {
@@ -11744,13 +11761,13 @@ void GrantRevokeNode::checkGrantorCanGrant(thread_db* tdbb, jrd_tra* transaction
 		{
 			if (fieldName == G_FLD.RDB$FIELD_NAME)
